import test from 'node:test';
import assert from 'node:assert/strict';
import createHost from './host.impl.ts';

test('basic flow', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.acquire('c0')).ok, false);
  assert.equal((await h.acquire('x')).ok, false);
  assert.equal(await h.client('x'), null);
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  await h.write('c0');
  assert.equal((await h.write('c0')).ok, false);
  await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  await h.acquire('c1');
  await h.deliverAll();
  assert.equal((await h.client('c1'))!.status, 'idle');
  await h.release('c0');
  await h.deliverAll();
  assert.equal((await h.lease()).holder, null);
});

test('revoked before granted', async () => {
  const h = await createHost();
  await h.acquire('c1');
  const [acq] = await h.inFlight();
  await h.deliver(acq.id);
  await h.expire();
  const rev = (await h.inFlight()).find((m) => m.action === 'Revoked')!;
  await h.deliver(rev.id);
  await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'idle', token: 1, writing: false });
  assert.equal((await h.lease()).holder, null);
});

test('stale write refused', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.write('c0');
  await h.expire();
  await h.acquire('c1');
  const ms = await h.inFlight();
  await h.deliver(ms.find((m) => m.action === 'Acquire')!.id);
  await h.deliver(ms.find((m) => m.action === 'Write')!.id);
  assert.equal((await h.lease()).writes, 0);
  await h.deliverAll();
  assert.equal((await h.lease()).holder, 'c1');
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
});

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 2: acknowledge a release

A client that gives the lease back now waits until the service has taken it back.

- `release(client)`: a client holding the lease becomes **releasing** (not idle) and sends `Release` as before.
- On a release, the service now always answers `Released` with data `{}`, whether it took the lease back or ignored the release.
- On `Released`, a releasing client becomes **idle**. `acquire` is refused while the client is releasing, and a releasing client ignores `Revoked`.

`status` in the client view can now also be `"releasing"`. Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T10 after change 2, a lease with fencing tokens and acknowledged releases: the host interface every arm implements (PT13, S91).

/** A message sent by one part of the system to another, not yet delivered. */
export interface Message {
  id: string;
  from: string;
  to: string;
  action: string;
  data: Record<string, unknown>;
}

/** The network: nothing is delivered until deliver or deliverAll is called. */
export interface Network {
  /** Every message in transit, in no promised order. */
  inFlight(): Promise<Message[]>;
  /** Deliver one message in transit, by its id. */
  deliver(id: string): Promise<void>;
  /** Deliver every message in transit, and every message those deliveries send, until none is left. */
  deliverAll(): Promise<void>;
}

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

export interface ClientView {
  status: 'idle' | 'requesting' | 'holding' | 'releasing';
  token: number;
  writing: boolean;
}

export interface Host extends Network {
  acquire(client: string): Promise<Outcome>;
  release(client: string): Promise<Outcome>;
  write(client: string): Promise<Outcome>;
  expire(): Promise<Outcome>;
  lease(): Promise<{ holder: string | null; token: number; writes: number }>;
  /** The client "c0" or "c1", or null for any other id. */
  client(client: string): Promise<ClientView | null>;
}

/** The module's default export: a factory of a fresh system, with the lease service and two idle clients. */
export type CreateHost = () => Promise<Host>;
```

Update your delivery to satisfy the brief as changed, keeping everything the change does not touch. Test your work as you go. When you are done, say so in one line.

